def connected_components(nodes, edges):
    # Build adjacency list
    adj = {node: [] for node in nodes}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = set()
    components = []
    for node in nodes:
        if node not in visited:
            stack = [node]
            component = []
            while stack:
                cur = stack.pop()
                if cur in visited:
                    continue
                visited.add(cur)
                component.append(cur)
                for neighbor in adj.get(cur, []):
                    if neighbor not in visited:
                        stack.append(neighbor)
            component.sort()
            components.append(component)
    components.sort(key=lambda x: x[0] if x else -1)
    return components
